#!/usr/bin/env python3

import binascii
import sys

def getNibbleLength(offset):
    if str(offset)[0] == "9":
        return len(str(offset)) + 1
    return len(str(offset))

def decodeText(encodedText, offset):
    nibbleLen = getNibbleLength(offset)
    hex_string = ""

    # Process the encoded text in chunks of nibbleLen
    for i in range(0, len(encodedText), nibbleLen):
        chunk = encodedText[i:i+nibbleLen]
        if not chunk.isdigit():
            continue

        # Convert chunk to integer and subtract offset
        value = int(chunk) - offset

        # Value should be between 0-15 (hex nibble)
        if 0 <= value <= 9:
            hex_char = str(value)
        elif 10 <= value <= 15:
            hex_char = chr(87 + value)  # 'a' to 'f'
        else:
            # Something went wrong
            print(f"Warning: Invalid value after offset subtraction: {value}")
            continue

        hex_string += hex_char

    # Convert hex string to binary data
    try:
        binary_data = binascii.unhexlify(hex_string)
        return binary_data
    except binascii.Error as e:
        print(f"Error decoding hex: {e}")
        # If odd-length, try adding a trailing zero
        if len(hex_string) % 2 == 1:
            hex_string += "0"
            return binascii.unhexlify(hex_string)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python decode.py <encoded_file> <output_file>")
        sys.exit(1)

    encoded_file = sys.argv[1]
    output_file = sys.argv[2]
    offset = 9133337  # As specified in the challenge

    with open(encoded_file, 'r') as f:
        encoded_data = f.read()

    binary_data = decodeText(encoded_data, offset)

    with open(output_file, 'wb') as f:
        f.write(binary_data)

    print(f"Decoded data written to {output_file}")
    # Print a hexdump preview of the first few bytes
    print("\nHexdump preview:")
    import binascii
    if binary_data:
        preview = binascii.hexlify(binary_data[:32]).decode()
        for i in range(0, len(preview), 2):
            print(preview[i:i+2], end=" ")

